const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body ?? item;
const receivedToken = headers['x-workflow-token'] ?? headers['X-Workflow-Token'];
if (!receivedToken || receivedToken !== $env.N8N_WORKFLOW_TOKEN) {
  throw new Error('Invalid x-workflow-token');
}
if (body.trigger !== 'engagement.score_renewal_risk_requested') {
  throw new Error(`Unexpected trigger: ${body.trigger ?? 'missing'}`);
}
if (!body.engagement_id) {
  throw new Error('Missing engagement_id');
}
if (!body.agent_run_id) {
  throw new Error('Missing agent_run_id');
}
return [{ json: { trigger: body.trigger, engagement_id: body.engagement_id, agent_run_id: body.agent_run_id } }];

const context = $input.first().json;
const triggerPayload = $('Validate Trigger').first().json;
const engagement = context.engagement ?? {};
const agentRunId = context.agent_run?.id ?? context.agent_run_id ?? triggerPayload.agent_run_id;
const touchpoints = Array.isArray(context.recent_touchpoints) ? context.recent_touchpoints : [];
const overdueTasks = context.open_overdue_task_count ?? 0;
const today = new Date().toISOString().slice(0, 10);
const lastTouch = touchpoints[0]?.occurred_at ?? engagement.last_touch_at ?? null;
const daysSinceTouch = lastTouch ? Math.floor((Date.parse(today) - Date.parse(lastTouch)) / 86400000) : null;
const negativeCount = touchpoints.filter((t) => t.sentiment === 'negative').length;
let score = 70;
const reasons = [];
if (daysSinceTouch === null || daysSinceTouch > 30) { score -= 25; reasons.push(daysSinceTouch === null ? 'no touchpoint on record' : `${daysSinceTouch} days since last touch`); }
if (negativeCount > 0) { score -= 20 * negativeCount; reasons.push(`${negativeCount} recent negative touchpoint(s)`); }
if (overdueTasks > 0) { score -= 10 * Math.min(overdueTasks, 3); reasons.push(`${overdueTasks} overdue task(s)`); }
score = Math.max(0, Math.min(100, score));
const renewalRisk = score < 40 ? 'high' : score < 65 ? 'medium' : 'low';
const fallback = {
  engagement_id: engagement.id ?? triggerPayload.engagement_id,
  agent_run_id: agentRunId,
  health_score: score,
  renewal_risk: renewalRisk,
  risk_reasoning: `Deterministic staging fallback: ${reasons.length > 0 ? reasons.join('; ') : 'no risk signals detected'}.`,
  suggested_next_action: renewalRisk === 'high' ? 'Schedule an urgent check-in before renewal' : renewalRisk === 'medium' ? 'Schedule a check-in this month' : 'Maintain regular cadence',
  output_summary: `Fallback renewal risk scored ${renewalRisk} (${score}/100).`,
  confidence: 0.6,
  model_used: 'deterministic-fallback'
};
const model = $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-6';
const openrouter_request = {
  model,
  messages: [
    { role: 'system', content: 'Return only JSON matching the ClientOps renewal-risk writeback contract. Do not include markdown.' },
    { role: 'user', content: JSON.stringify({ context, required_fields: ['engagement_id', 'agent_run_id', 'health_score', 'renewal_risk', 'risk_reasoning', 'suggested_next_action', 'confidence', 'output_summary'] }) }
  ],
  response_format: { type: 'json_object' }
};
return [{ json: { context, fallback, openrouter_request, openrouter_configured: Boolean($env.OPENROUTER_API_KEY) } }];

const prepared = $('Prepare Fallback / AI Request').first().json;
const fallback = prepared.fallback;
const response = $input.first()?.json ?? {};

function parsePayload(value) {
  const content = value.choices?.[0]?.message?.content;
  if (typeof content === 'string') {
    try { return JSON.parse(content); } catch (error) { return undefined; }
  }
  return isPlainObject(content) ? content : undefined;
}
function isPlainObject(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function finiteNumber(value, fallbackValue) { const number = typeof value === 'number' ? value : Number(value); return Number.isFinite(number) ? number : fallbackValue; }
function clampNumber(value, fallbackValue, min, max) { return Math.min(max, Math.max(min, finiteNumber(value, fallbackValue))); }
function safeString(value, fallbackValue, maxLength = 1200) { return typeof value === 'string' && value.trim() ? value.trim().slice(0, maxLength) : fallbackValue; }
function safeRisk(value, fallbackValue) { return ['low', 'medium', 'high'].includes(value) ? value : fallbackValue; }

const parsed = parsePayload(response);

const output = {
  engagement_id: fallback.engagement_id,
  agent_run_id: fallback.agent_run_id,
  health_score: clampNumber(parsed?.health_score, fallback.health_score, 0, 100),
  renewal_risk: safeRisk(parsed?.renewal_risk, fallback.renewal_risk),
  risk_reasoning: safeString(parsed?.risk_reasoning, fallback.risk_reasoning),
  suggested_next_action: safeString(parsed?.suggested_next_action, fallback.suggested_next_action, 200),
  confidence: clampNumber(parsed?.confidence, fallback.confidence, 0, 1),
  output_summary: safeString(parsed?.output_summary, fallback.output_summary),
  model_used: safeString(parsed?.model_used, fallback.model_used, 120),
};
return [{ json: output }];
